/* Margin — Issue 14
   A small, local design system: paper, ink, one oxide red. */

:root {
  --paper: #f2ede2;
  --paper-deep: #e7dfcd;
  --ink: #191713;
  --ink-soft: #59534a;
  --rule: #c8bfae;
  --accent: #a63c1e;
  --accent-light: #f0b7a1;
  --ok: #cfe2b7;
  --serif: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Palatino, Georgia, "Times New Roman", serif;
  --sans: "Helvetica Neue", Helvetica, Arial, "Liberation Sans", sans-serif;
  --mono: "SFMono-Regular", Menlo, Consolas, "Liberation Mono", monospace;
  --pad: clamp(20px, 4.6vw, 72px);
  --ease: cubic-bezier(0.2, 0.6, 0.2, 1);
  color-scheme: light;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 24px;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background-color: var(--paper);
  background-image:
    radial-gradient(120% 80% at 85% -10%, rgba(255, 255, 255, 0.42), transparent 60%),
    radial-gradient(90% 60% at 0% 100%, rgba(120, 96, 55, 0.07), transparent 55%);
  background-attachment: fixed;
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img,
svg {
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration-thickness: 1px;
  text-underline-offset: 4px;
}

p,
h1,
h2,
h3,
figure,
dl,
dd {
  margin: 0;
}

ul,
ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

button,
input {
  font: inherit;
  color: inherit;
}

::selection {
  background: var(--accent);
  color: var(--paper);
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.shell {
  width: min(100% - (2 * var(--pad)), 1360px);
  margin-inline: auto;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  top: 10px;
  left: 10px;
  z-index: 100;
  padding: 12px 16px;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  transform: translateY(-150%);
}

.skip-link:focus {
  transform: translateY(0);
}

/* ---------- Masthead ---------- */

.masthead {
  padding-top: 16px;
}

.topline {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 6px 24px;
  padding-bottom: 13px;
  border-bottom: 1px solid var(--rule);
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: 0.16em;
  line-height: 1.4;
  text-transform: uppercase;
}

.masthead__main {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(250px, 370px);
  align-items: end;
  gap: 24px 48px;
  padding: 10px 0 24px;
  border-bottom: 3px solid var(--ink);
}

.wordmark {
  display: inline-block;
  margin-left: -0.055em;
  font-family: var(--serif);
  font-size: clamp(4.75rem, 23vw, 15rem);
  font-weight: 400;
  letter-spacing: -0.055em;
  line-height: 0.74;
  text-decoration: none;
}

.wordmark__dot {
  color: var(--accent);
}

.masthead__aside {
  padding-bottom: 4px;
}

.masthead__note {
  max-width: 30ch;
  margin-left: auto;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--rule);
  color: var(--ink-soft);
  font-family: var(--serif);
  font-size: 14px;
  font-style: italic;
  line-height: 1.45;
  text-align: right;
}

.nav {
  margin-top: 10px;
}

.nav ul {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 4px 22px;
}

.nav a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.15em;
  text-decoration: none;
  text-transform: uppercase;
}

.nav a:hover {
  color: var(--accent);
}

.mode-toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  margin-top: 3px;
  padding: 0 11px;
  border: 1px solid var(--ink);
  border-radius: 0;
  background: transparent;
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background-color 160ms var(--ease), color 160ms var(--ease);
}

.mode-toggle__icon {
  width: 13px;
  height: 13px;
  flex: none;
}

.mode-toggle:hover {
  background: rgba(25, 23, 19, 0.07);
}

.mode-toggle[aria-pressed="true"] {
  background: var(--ink);
  color: var(--paper);
}

.mode-toggle[aria-pressed="true"] .mode-toggle__icon {
  color: var(--accent-light);
}

/* ---------- Hero ---------- */

.hero__grid {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(290px, 0.82fr);
  align-items: start;
  gap: clamp(32px, 5vw, 84px);
  padding-top: clamp(38px, 5.5vw, 76px);
  padding-bottom: clamp(56px, 7.5vw, 108px);
}

.hero__copy {
  max-width: 780px;
}

.kicker {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.17em;
  line-height: 1.5;
  text-transform: uppercase;
}

.kicker__mark {
  width: 7px;
  height: 7px;
  flex: none;
  background: var(--accent);
}

.kicker__sep {
  color: var(--accent);
}

.hero__title {
  margin-top: clamp(26px, 3vw, 42px);
  font-family: var(--serif);
  font-size: clamp(3.6rem, 9.2vw, 8.9rem);
  font-weight: 400;
  letter-spacing: -0.052em;
  line-height: 0.86;
  text-wrap: balance;
}

.hero__line {
  display: block;
}

.hero__line--indent {
  padding-left: 0.62em;
}

.hero__line--last {
  padding-left: 0.06em;
}

.hero__title em {
  font-style: italic;
  letter-spacing: -0.062em;
}

.hero__dek {
  max-width: 44ch;
  margin-top: clamp(30px, 3.6vw, 46px);
  color: #4d473e;
  font-family: var(--serif);
  font-size: clamp(1.06rem, 1.35vw, 1.32rem);
  line-height: 1.58;
}

.byline {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 8px 24px;
  max-width: 520px;
  margin-top: clamp(28px, 3vw, 38px);
  padding-top: 13px;
  border-top: 1px solid var(--rule);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: 0.13em;
  line-height: 1.6;
  text-transform: uppercase;
}

.byline strong {
  font-weight: 600;
}

.jump {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-top: 34px;
  padding-bottom: 5px;
  border-bottom: 1px solid var(--ink);
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.14em;
  text-decoration: none;
  text-transform: uppercase;
  transition: color 160ms var(--ease), border-color 160ms var(--ease);
}

.jump span {
  font-size: 14px;
  line-height: 1;
  transition: transform 180ms var(--ease);
}

.jump:hover {
  color: var(--accent);
  border-color: var(--accent);
}

.jump:hover span {
  transform: translateX(3px);
}

/* Plate */

.plate {
  width: 100%;
  max-width: 520px;
  justify-self: end;
  margin-top: clamp(0px, 1.5vw, 20px);
}

.plate__head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 9px;
  border-bottom: 1px solid var(--ink);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.15em;
  line-height: 1.4;
  text-transform: uppercase;
}

.plate__art {
  display: block;
  width: 100%;
  height: auto;
  margin-top: 10px;
  border: 1px solid rgba(25, 23, 19, 0.22);
}

.plate__caption {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 12px;
  margin-top: 12px;
  padding-top: 9px;
  border-top: 1px solid var(--rule);
  color: var(--ink-soft);
  font-family: var(--sans);
  font-size: 10.5px;
  line-height: 1.55;
}

.plate__caption span {
  color: var(--ink);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

/* ---------- Section furniture ---------- */

.section-label {
  display: flex;
  align-items: baseline;
  gap: 10px;
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: 0.17em;
  line-height: 1.4;
  text-transform: uppercase;
}

.section-label span {
  color: var(--accent);
}

.section-label::before {
  content: "";
  width: 6px;
  height: 6px;
  flex: none;
  background: var(--accent);
  transform: translateY(-1px);
}

.section-label--light::before {
  background: var(--accent-light);
}

.section-label--light span {
  color: var(--accent-light);
}

/* ---------- Contents ---------- */

.contents {
  padding-block: clamp(46px, 6.5vw, 92px);
  border-top: 1px solid var(--ink);
}

.contents__grid {
  display: grid;
  grid-template-columns: minmax(190px, 0.8fr) minmax(0, 2.2fr);
  align-items: start;
  gap: clamp(28px, 5vw, 80px);
}

.contents__title {
  max-width: 13ch;
  margin-top: 22px;
  font-family: var(--serif);
  font-size: clamp(1.85rem, 3.1vw, 2.9rem);
  font-weight: 400;
  letter-spacing: -0.03em;
  line-height: 1.04;
}

.contents__title em {
  font-style: italic;
}

.contents__note {
  max-width: 32ch;
  margin-top: 20px;
  color: var(--ink-soft);
  font-family: var(--serif);
  font-size: 14.5px;
  line-height: 1.55;
}

.stories {
  border-top: 1px solid var(--ink);
}

.story {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) 142px;
  gap: 12px 24px;
  padding: 28px 0 30px;
  border-bottom: 1px solid var(--rule);
}

.story__num {
  padding-top: 9px;
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: 0.1em;
  transition: color 160ms var(--ease);
}

.story__title {
  font-family: var(--serif);
  font-size: clamp(1.6rem, 2.7vw, 2.35rem);
  font-weight: 400;
  letter-spacing: -0.028em;
  line-height: 1.08;
  transition: color 160ms var(--ease);
}

.story__dek {
  max-width: 54ch;
  margin-top: 10px;
  color: var(--ink-soft);
  font-family: var(--serif);
  font-size: 15px;
  line-height: 1.55;
}

.story__meta {
  padding-top: 8px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.11em;
  line-height: 1.9;
  text-align: right;
  text-transform: uppercase;
}

.story__meta span {
  color: var(--ink-soft);
}

.story:hover .story__title,
.story:hover .story__num {
  color: var(--accent);
}

/* ---------- Archive ---------- */

.archive {
  padding-block: 30px;
  border-block: 1px solid var(--ink);
  background: var(--paper-deep);
}

.archive__grid {
  display: grid;
  grid-template-columns: minmax(150px, 0.9fr) minmax(0, 2.6fr);
  align-items: center;
  gap: clamp(20px, 4vw, 60px);
}

.archive__title {
  margin-top: 12px;
  font-family: var(--serif);
  font-size: clamp(1.6rem, 2.4vw, 2.1rem);
  font-weight: 400;
  letter-spacing: -0.02em;
}

.archive__list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.archive__item {
  display: flex;
  align-items: baseline;
  gap: 13px;
  padding-left: 18px;
  border-left: 1px solid var(--rule);
}

.archive__no {
  font-family: var(--serif);
  font-size: 2.5rem;
  letter-spacing: -0.05em;
  line-height: 0.9;
}

.archive__name {
  font-family: var(--serif);
  font-size: 1.05rem;
  line-height: 1.18;
}

.archive__meta {
  margin-top: 4px;
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

/* ---------- Subscribe ---------- */

.subscribe {
  padding-block: clamp(64px, 9vw, 126px);
  background: var(--ink);
  color: var(--paper);
}

.subscribe__grid {
  display: grid;
  grid-template-columns: minmax(0, 1.12fr) minmax(320px, 0.88fr);
  align-items: start;
  gap: clamp(40px, 6vw, 96px);
}

.subscribe__title {
  max-width: 11ch;
  margin-top: 24px;
  font-family: var(--serif);
  font-size: clamp(2.7rem, 5.4vw, 5.1rem);
  font-weight: 400;
  letter-spacing: -0.04em;
  line-height: 0.94;
}

.subscribe__title em {
  font-style: italic;
}

.subscribe__lede {
  max-width: 42ch;
  margin-top: 26px;
  color: rgba(242, 237, 226, 0.74);
  font-family: var(--serif);
  font-size: 1.06rem;
  line-height: 1.6;
}

.specs {
  max-width: 440px;
  margin-top: clamp(32px, 4vw, 52px);
}

.specs div {
  display: grid;
  grid-template-columns: 120px minmax(0, 1fr);
  gap: 16px;
  padding: 12px 0;
  border-top: 1px solid rgba(242, 237, 226, 0.22);
}

.specs div:last-child {
  border-bottom: 1px solid rgba(242, 237, 226, 0.22);
}

.specs dt {
  color: rgba(242, 237, 226, 0.6);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.14em;
  line-height: 1.9;
  text-transform: uppercase;
}

.specs dd {
  font-family: var(--serif);
  font-size: 1rem;
  line-height: 1.5;
}

.offer {
  padding: clamp(24px, 3vw, 40px);
  border: 1px solid rgba(242, 237, 226, 0.32);
}

.offer__eyebrow {
  color: rgba(242, 237, 226, 0.66);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.16em;
  line-height: 1.5;
  text-transform: uppercase;
}

.offer__price {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px 10px;
  margin-top: 14px;
  padding-bottom: 18px;
  border-bottom: 1px solid rgba(242, 237, 226, 0.28);
  font-family: var(--serif);
  font-size: clamp(3.4rem, 5.5vw, 4.9rem);
  letter-spacing: -0.045em;
  line-height: 1;
}

.offer__currency {
  font-size: 0.46em;
  letter-spacing: 0;
}

.offer__per {
  color: rgba(242, 237, 226, 0.7);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.offer__terms {
  margin-top: 14px;
  color: rgba(242, 237, 226, 0.8);
  font-family: var(--serif);
  font-size: 14px;
  line-height: 1.5;
}

.signup {
  margin-top: 28px;
}

.signup__label {
  display: block;
  margin-bottom: 6px;
  color: rgba(242, 237, 226, 0.66);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.signup__field {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.signup input {
  width: 100%;
  padding: 10px 0;
  border: 0;
  border-bottom: 1px solid rgba(242, 237, 226, 0.48);
  border-radius: 0;
  background: transparent;
  color: var(--paper);
  font-family: var(--serif);
  font-size: 1.22rem;
  line-height: 1.4;
  transition: border-color 160ms var(--ease);
}

.signup input::placeholder {
  color: rgba(242, 237, 226, 0.34);
}

.signup input:focus {
  border-bottom-color: var(--paper);
  outline: 2px solid rgba(242, 237, 226, 0.75);
  outline-offset: 4px;
}

.signup__button {
  min-height: 50px;
  padding: 12px 20px;
  border: 1px solid var(--paper);
  border-radius: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background-color 160ms var(--ease), color 160ms var(--ease), border-color 160ms var(--ease);
}

.signup__button:hover {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--paper);
}

.signup__button:active {
  transform: translateY(1px);
}

.signup__note {
  margin-top: 10px;
  color: rgba(242, 237, 226, 0.55);
  font-size: 11px;
  line-height: 1.5;
}

.form-msg {
  min-height: 1.5em;
  margin-top: 8px;
  font-family: var(--sans);
  font-size: 12.5px;
  line-height: 1.5;
}

.form-msg.is-error {
  color: var(--accent-light);
}

.form-msg.is-success {
  color: var(--ok);
}

.signup.is-error input {
  border-bottom-color: var(--accent-light);
}

.signup.is-success input {
  border-bottom-color: var(--ok);
}

.offer__fineprint {
  margin-top: 18px;
  color: rgba(242, 237, 226, 0.42);
  font-size: 10.5px;
  line-height: 1.5;
}

/* ---------- Footer ---------- */

.footer {
  padding-block: 30px 42px;
}

.footer__grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr) minmax(0, 1.2fr);
  align-items: start;
  gap: 24px 40px;
}

.footer__mark {
  font-family: var(--serif);
  font-size: 1.9rem;
  letter-spacing: -0.05em;
  line-height: 1;
}

.footer__mark span {
  color: var(--accent);
}

.footer__line {
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.09em;
  line-height: 1.8;
  text-transform: uppercase;
}

.footer__line:last-child {
  text-align: right;
}

.footer__line a {
  text-decoration: none;
  border-bottom: 1px solid var(--rule);
}

.footer__line a:hover {
  color: var(--accent);
  border-color: var(--accent);
}

/* ---------- Reading mode ---------- */

html[data-reading="true"] {
  --paper: #fbf7ec;
  --paper-deep: #f1ead9;
}

html[data-reading="true"] body {
  background-image: none;
  font-size: 18px;
}

html[data-reading="true"] .topline {
  display: none;
}

html[data-reading="true"] .masthead {
  position: sticky;
  top: 0;
  z-index: 40;
  padding-top: 0;
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

html[data-reading="true"] .masthead__main {
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 18px 32px;
  padding: 9px 0;
  border-bottom: 0;
}

html[data-reading="true"] .wordmark {
  font-size: clamp(1.55rem, 2.4vw, 2.1rem);
  line-height: 1;
}

html[data-reading="true"] .masthead__note {
  display: none;
}

html[data-reading="true"] .nav {
  margin-top: 0;
}

html[data-reading="true"] .nav ul {
  gap: 2px 18px;
}

html[data-reading="true"] .nav a {
  min-height: 36px;
  font-size: 9px;
}

html[data-reading="true"] .mode-toggle {
  min-height: 34px;
}

html[data-reading="true"] .hero__grid {
  grid-template-columns: minmax(0, 1fr);
  gap: 0;
  padding-top: clamp(30px, 4vw, 54px);
}

html[data-reading="true"] .hero__copy {
  max-width: 74ch;
}

html[data-reading="true"] .hero__title {
  max-width: 18ch;
  font-size: clamp(2.7rem, 5.6vw, 4.9rem);
  line-height: 0.95;
}

html[data-reading="true"] .hero__dek {
  max-width: 58ch;
  color: var(--ink-soft);
  font-size: 1.24rem;
  line-height: 1.7;
}

html[data-reading="true"] .plate {
  display: none;
}

html[data-reading="true"] .contents__grid {
  grid-template-columns: minmax(0, 1fr);
  gap: 34px;
}

html[data-reading="true"] .contents__title {
  max-width: 22ch;
}

