/* Margin — small enhancements.
   Reading mode and inline subscription validation. Nothing leaves the page. */

(function () {
  "use strict";

  var root = document.documentElement;
  var toggle = document.getElementById("reading-toggle");
  var status = document.getElementById("mode-status");
  var STORAGE_KEY = "margin:reading-mode";

  var emailForm = document.getElementById("signup");
  var emailInput = document.getElementById("email");
  var emailMsg = document.getElementById("email-msg");

  var EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

  function announce(message) {
    if (!status) return;
    status.textContent = "";
    window.setTimeout(function () {
      status.textContent = message;
    }, 40);
  }

  /* ---------- Reading mode ---------- */

  function applyReadingMode(on, shouldAnnounce) {
    if (on) {
      root.setAttribute("data-reading", "true");
    } else {
      root.removeAttribute("data-reading");
    }

    if (toggle) {
      toggle.setAttribute("aria-pressed", on ? "true" : "false");
      toggle.setAttribute("title", on ? "Leave reading mode" : "Enter reading mode");
    }

    if (shouldAnnounce) {
      announce(on ? "Reading mode on. Larger type, quieter page." : "Reading mode off.");
    }
  }

  function storedPreference() {
    try {
      return window.localStorage.getItem(STORAGE_KEY) === "on";
    } catch (error) {
      return false;
    }
  }

  function rememberPreference(on) {
    try {
      window.localStorage.setItem(STORAGE_KEY, on ? "on" : "off");
    } catch (error) {
      /* Storage can be unavailable; the control still works for this visit. */
    }
  }

  if (toggle) {
    applyReadingMode(storedPreference(), false);

    toggle.addEventListener("click", function () {
      var next = toggle.getAttribute("aria-pressed") !== "true";
      applyReadingMode(next, true);
      rememberPreference(next);
    });

    document.addEventListener("keydown", function (event) {
      if (event.key !== "Escape") return;
      if (root.getAttribute("data-reading") !== "true") return;

      var active = document.activeElement;
      if (active && (active.tagName === "INPUT" || active.tagName === "TEXTAREA")) return;

      applyReadingMode(false, true);
      rememberPreference(false);
    });
  }

  /* ---------- Email field ---------- */

  function setMessage(text, state) {
    if (!emailMsg) return;
    emailMsg.textContent = text;
    emailMsg.classList.remove("is-error", "is-success");
    if (state) emailMsg.classList.add("is-" + state);
  }

  function setFieldState(state) {
    if (!emailForm || !emailInput) return;
    emailForm.classList.remove("is-error", "is-success");
    if (state) emailForm.classList.add("is-" + state);
    emailInput.setAttribute("aria-invalid", state === "error" ? "true" : "false");
  }

  function validate(value) {
    if (!value) {
      return "Enter your email address to continue.";
    }
    if (!EMAIL_PATTERN.test(value)) {
      return "That address does not look right. Try name@domain.com.";
    }
    return "";
  }

  if (emailForm && emailInput) {
    emailForm.addEventListener("submit", function (event) {
      event.preventDefault();
      var value = emailInput.value.trim();
      var problem = validate(value);

      if (problem) {
        setFieldState("error");
        setMessage(problem, "error");
        emailInput.focus();
        return;
      }

      setFieldState("success");
      setMessage("Thank you — you are on the list for Issue 14. No payment has been taken.", "success");
      announce("Subscribed for this demonstration. No email was sent.");
    });

    emailInput.addEventListener("input", function () {
      var value = emailInput.value.trim();

      if (emailForm.classList.contains("is-success")) {
        setFieldState(null);
        setMessage("", null);
        return;
      }

      if (emailForm.classList.contains("is-error") && value && !validate(value)) {
        setFieldState(null);
        setMessage("", null);
      }
    });

    emailInput.addEventListener("blur", function () {
      var value = emailInput.value.trim();
      if (!value) return;

      var problem = validate(value);
      if (problem) {
        setFieldState("error");
        setMessage(problem, "error");
      }
    });
  }
})();
